package com.nigson.acceptance.carrier;

import java.time.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.integration.carrier.*;
import com.nigson.integration.providers.*;
import com.nigson.integration.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import static org.assertj.core.api.Assertions.*;

/** Native owned DB plus actual FedEx OAuth/rate HTTP; synthetic addresses never reach genuine endpoints. */
class CarrierQuotePersistenceTest {
 private JdbcTemplate jdbc,admin;private CarrierQuoteService service;private HttpServer server;private Clock clock;private PlatformStore store;private AuditWriter audit;private CarrierProvider provider;
 private final AtomicInteger calls=new AtomicInteger();private final List<String> violations=new ArrayList<>();private final UUID party=UUID.randomUUID(),cart=UUID.randomUUID();private volatile String currency="NGN",amount="1234.56";
 @BeforeEach void setup()throws Exception{
  String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native isolated owned PostgreSQL required");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_INTEGRATION_DB_REQUIRED");
  var ds=new DriverManagerDataSource(url+"?currentSchema=integration","nigson_integration_app","mock-integration-runtime");jdbc=new JdbcTemplate(ds);admin=new JdbcTemplate(new DriverManagerDataSource(url,"nigson_bootstrap","mock-bootstrap"));clock=Clock.systemUTC();var metrics=new SimpleMeterRegistry();store=new PlatformStore(jdbc,new DataSourceTransactionManager(ds),clock,metrics);audit=new AuditWriter(jdbc,clock,metrics);
  server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",x->{var body=EventCodec.JSON.readTree(x.getRequestURI().getPath().equals("/oauth/token")?"{}":new String(x.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));String response;if(x.getRequestURI().getPath().equals("/oauth/token")){x.getRequestBody().readAllBytes();response="{\"access_token\":\"mock-token\",\"token_type\":\"bearer\",\"expires_in\":3600}";}else{calls.incrementAndGet();if(!body.path("accountNumber").path("value").asString().equals("mock-fedex-account"))violations.add("ACCOUNT");response="{\"output\":{\"rateReplyDetails\":[{\"serviceType\":\"SYNTHETIC_SERVICE\",\"ratedShipmentDetails\":[{\"rateType\":\"ACCOUNT\",\"totalNetCharge\":"+amount+",\"shipmentRateDetail\":{\"currency\":\""+currency+"\"}}]}]}}";}byte[] bytes=response.getBytes(java.nio.charset.StandardCharsets.UTF_8);x.getResponseHeaders().add("Content-Type","application/json");x.sendResponseHeaders(200,bytes.length);x.getResponseBody().write(bytes);x.close();});server.start();
  var actual=new FedExAdapter("test",ProviderHttp.Mode.MOCK,"http://127.0.0.1:"+server.getAddress().getPort(),"mock-fedex-client","mock-fedex-secret","mock-fedex-account");
  provider=new CarrierProvider(){public ProviderHttp.Mode mode(){return actual.mode();}public tools.jackson.databind.JsonNode rates(tools.jackson.databind.JsonNode request){assertThat(TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return actual.rates(request);}public tools.jackson.databind.JsonNode book(tools.jackson.databind.JsonNode n){throw new AssertionError("QUOTE_CANNOT_BOOK");}public tools.jackson.databind.JsonNode cancel(String n){throw new AssertionError("QUOTE_CANNOT_CANCEL");}public tools.jackson.databind.JsonNode track(String n){throw new AssertionError("QUOTE_CANNOT_TRACK");}public tools.jackson.databind.JsonNode trackReference(String r,LocalDate b,LocalDate e){throw new AssertionError("QUOTE_CANNOT_RECONCILE");}};
  service=service(clock.instant().plusSeconds(600));
 }
 private CarrierQuoteService service(Instant until){return new CarrierQuoteService(provider,store,audit,clock,Set.of("SYNTHETIC_SERVICE"),"MOCK","SYNTHETIC_SERVICE","DROPOFF_AT_FEDEX_LOCATION","synthetic-offline-approval",until);}
 @AfterEach void cleanup(){if(server!=null)server.stop(0);if(jdbc!=null){jdbc.update("DELETE FROM integration.idempotency_record WHERE principal_key=?","nigson-commerce:carrier:"+party);assertThat(violations).isEmpty();}}
 private PrivateWorkload.Proof proof(){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-182")).findFirst().orElseThrow();return new PrivateWorkload.Proof("nigson-commerce","synthetic-workload",route,new ActorAssertion.Actor(party,"https://synthetic-issuer.invalid","synthetic-customer",null,Set.of("CUSTOMER"),Set.of(route.scope()),null));}
 private CarrierValues.QuoteInput input(UUID command){var address=new CarrierValues.Address("Synthetic Recipient","+2348000000001","Synthetic Street",null,"Lagos","LA",null,"NG");return new CarrierValues.QuoteInput(command,cart,"NG","NGN",address,address,List.of(new CarrierValues.Parcel(UUID.randomUUID(),"1","1","10","10","10")),null);}
 @Test void acknowledgementReplaysOneAuditedRateWithoutAddresses(){var input=input(UUID.randomUUID());var first=service.quote(proof(),input,UUID.randomUUID());amount="999";var replay=service.quote(proof(),input,UUID.randomUUID());assertThat(replay).isEqualTo(first);assertThat(first.amount()).isEqualTo("1234.56");assertThat(first.expiresAt()).isBetween(clock.instant().plusSeconds(290),clock.instant().plusSeconds(301));assertThat(calls.get()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,cart)).isEqualTo(1);String body=jdbc.queryForObject("SELECT response_body::text FROM integration.idempotency_record WHERE principal_key=?",String.class,"nigson-commerce:carrier:"+party);assertThat(body).doesNotContain("Synthetic Street","+234","recipient","accountNumber");}
 @Test void auditFailureCannotAcknowledgeAndSameReadCommandRecovers(){var input=input(UUID.randomUUID());admin.execute("REVOKE INSERT ON integration.audit_record FROM nigson_integration_app");try{assertThatThrownBy(()->service.quote(proof(),input,UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);}finally{admin.execute("GRANT INSERT ON integration.audit_record TO nigson_integration_app");}assertThat(jdbc.queryForObject("SELECT state FROM integration.idempotency_record WHERE principal_key=?",String.class,"nigson-commerce:carrier:"+party)).isEqualTo("FAILED_RETRYABLE");assertThat(service.quote(proof(),input,UUID.randomUUID()).amount()).isEqualTo("1234.56");assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,cart)).isEqualTo(1);}
 @Test void wrongCurrencyOrThirdDecimalNeverPersistsAnAcknowledgement(){var input=input(UUID.randomUUID());currency="USD";assertThatThrownBy(()->service.quote(proof(),input,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);currency="NGN";amount="12.340";assertThatThrownBy(()->service.quote(proof(),input,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.idempotency_record WHERE principal_key=?",Integer.class,"nigson-commerce:carrier:"+party)).isZero();}
 @Test void invalidTrustOrExpiredApprovalCannotCallProvider(){var input=input(UUID.randomUUID());var valid=proof();assertThatThrownBy(()->service.quote(new PrivateWorkload.Proof("nigson-experience",valid.subject(),valid.route(),valid.actor()),input,UUID.randomUUID())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->service.quote(new PrivateWorkload.Proof(valid.client(),valid.subject(),valid.route(),null),input,UUID.randomUUID())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);assertThatThrownBy(()->service(clock.instant().minusSeconds(1)).quote(valid,input,UUID.randomUUID())).isInstanceOf(Problem.Failure.class);assertThat(calls.get()).isZero();}
 @Test void sameCommandWithDifferentResourceBindingConflicts(){UUID command=UUID.randomUUID();var first=input(command);service.quote(proof(),first,UUID.randomUUID());assertThatThrownBy(()->service.quote(proof(),input(command),UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThat(jdbc.queryForObject("SELECT count(*) FROM integration.audit_record WHERE resource_id=?",Integer.class,cart)).isEqualTo(1);}
}
